package com.peiwan.platform.persistence.mapper;import com.baomidou.mybatisplus.core.metadata.IPage;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import org.apache.ibatis.annotations.*;import java.util.*;
public interface SystemLogQueryMapper{
 @Select("<script>select id,username,success,ip_address,user_agent,message,created_at from sys_login_log where username like concat('%',#{username},'%')<if test='success != null'> and success=#{success}</if> order by id desc</script>") IPage<Map<String,Object>> loginLogs(Page<Map<String,Object>> page,@Param("username")String username,@Param("success")Boolean success);
 @Select("select l.id,l.operator_id,u.username operator_name,l.operation,l.target_type,l.target_id,l.detail,l.ip_address,l.created_at from sys_operation_log l left join sys_user u on u.id=l.operator_id where coalesce(u.username,'') like concat('%',#{operator},'%') and l.operation like concat('%',#{operation},'%') and l.target_type like concat('%',#{targetType},'%') order by l.id desc") IPage<Map<String,Object>> operationLogs(Page<Map<String,Object>> page,@Param("operator")String operator,@Param("operation")String operation,@Param("targetType")String targetType);
}
